func valueDOTRandomDrawEntry(p unsafe.Pointer, c int32) any {
	r := (*dotrandom.DOTRandomDrawEntry)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DrawID)
	case 4:
		return string(r.WorkerID)
	case 5:
		return string(r.Substance)
	case 6:
		return r.Rank
	case 7:
		return string(r.Status)
	case 8:
		if r.NotifiedAt == nil {
			return nil
		}
		return *r.NotifiedAt
	case 9:
		if r.CompletedAt == nil {
			return nil
		}
		return *r.CompletedAt
	case 10:
		if r.TestID == "" {
			return nil
		}
		return string(r.TestID)
	case 11:
		if r.ExcuseReason == "" {
			return nil
		}
		return r.ExcuseReason
	case 12:
		return r.Version
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

