func newDOTRandomPool() unsafe.Pointer { return unsafe.Pointer(new(dotrandom.DOTRandomPool)) }

func newNDOTRandomPool(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]dotrandom.DOTRandomPool, n)))
}

func ptrDOTRandomPool(p unsafe.Pointer, c int32) any {
	r := (*dotrandom.DOTRandomPool)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return &r.Code
	case 4:
		return &r.Name
	case 5:
		return &r.Description
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return (*string)(unsafe.Pointer(&r.Period))
	case 8:
		return &r.DrugRatePercent
	case 9:
		return &r.AlcoholRatePercent
	case 10:
		return &r.IncludedDriverTypes
	case 11:
		return &r.IsDefault
	case 12:
		return &r.SearchVector
	case 13:
		return &r.Rank
	case 14:
		return &r.Version
	case 15:
		return &r.CreatedAt
	case 16:
		return &r.UpdatedAt
	}
	return nil
}

func valueDOTRandomPool(p unsafe.Pointer, c int32) any {
	r := (*dotrandom.DOTRandomPool)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return r.Code
	case 4:
		return r.Name
	case 5:
		if r.Description == "" {
			return nil
		}
		return r.Description
	case 6:
		return string(r.Status)
	case 7:
		return string(r.Period)
	case 8:
		return r.DrugRatePercent
	case 9:
		return r.AlcoholRatePercent
	case 10:
		if r.IncludedDriverTypes == nil {
			return keel.EmptyJSONArray
		}
		return r.IncludedDriverTypes
	case 11:
		return r.IsDefault
	case 12:
		return r.SearchVector
	case 13:
		return r.Rank
	case 14:
		return r.Version
	case 15:
		return r.CreatedAt
	case 16:
		return r.UpdatedAt
	}
	return nil
}

